/**
 * The lookup parts of an existing-Album review, rendered in the page's order without the rest of the page, their reads answered
 * per path: the status line with its next step and Details log (CatalogReviewStatus.tsx), the lookup details with conflicts and
 * their source-named answers, Track Artists, the expected tracklist, flags, the retry and the reference releases
 * (CatalogReviewLookupDetails.tsx), and the name box under a Look up another name toggle that opens by itself where the status
 * makes it the next step, as the page's row of alternatives does (CatalogReviewLookupAnother.tsx); polling, the detail re-read and
 * failures. All names and identifiers are synthetic.
 */
type Lookup = NonNullable<ReviewLookupResponse['lookup']>;
const applied = () => reviewAfterLookup(capturedCatalogReview());
const withLookup = (edit: (lookup: Lookup) => void, response = reviewLookupResponse()) => { edit(response.lookup!); return response; };
const notStarted = (lookupAvailable = true): ReviewLookupResponse => ({ lookup: null, revision: 1, valueRevision: 0, summary: { waiting: { lookup: false, analysis: false }, needsAnswer: { tie: false, conflicts: [] }, lookupAvailable, primaryArtists: [] } });

/**
 * The status line, the lookup details, and the name box under its toggle, as the page lays them out (AdminCatalogReviewPage.tsx):
 * the toggle shows while lookup is available, and the box opens where the status makes it the next step until the toggle is used
 * for that run.
 */
function Lookup({ item, disabled, error, onRun }: { item: CatalogReview; disabled: boolean; error: string | null; onRun: (action: string, payload: object) => void }) {
  const [next, setNext] = useState<LookupNext | null>(null), [another, setAnother] = useState<{ run: number; open: boolean } | null>(null);
  const open = Boolean(next?.available) && (another && another.run === next!.run ? another.open : Boolean(next?.box));
  return <>
    <CatalogReviewStatus item={item} onNext={setNext} />
    <CatalogReviewLookupDetails item={item} disabled={disabled} error={error} onRun={onRun} />
    {next?.available && <button type="button" aria-expanded={open} onClick={() => setAnother({ run: next.run, open: !open })}>Look up another name</button>}
    {open && <CatalogReviewLookupAnother item={item} disabled={disabled} onSubmit={(kind, text, artist) => onRun('lookup', { kind, text, ...(artist ? { artist } : {}) })}
      onCancel={() => setAnother({ run: next!.run, open: false })} />}
  </>;
}
/**
 * Renders the lookup parts; `lookup` answers its read (a body, or a function for each read), and the identity read is the
 * fixture's. `section` is everything rendered, `details` the Metadata lookup region.
 */
function mount(item: CatalogReview = applied(), lookup: ReviewLookupResponse | (() => Response | Promise<Response>) = reviewLookupResponse(), props: { disabled?: boolean; error?: string | null } = {}) {
  const fetch = vi.fn(async (path: string) => path.endsWith('/lookup') ? typeof lookup === 'function' ? lookup() : reviewJson(lookup)
    : path.endsWith('/candidates') ? reviewJson(reviewIdentityResponse()) : reviewJson({ code: 'unexpected' }, 500));
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const onRun = vi.fn(), invalidate = vi.spyOn(client, 'invalidateQueries');
  const element = (next: { item: CatalogReview; disabled?: boolean; error?: string | null }) => <QueryClientProvider client={client}><MemoryRouter>
    <div data-testid="lookup"><Lookup item={next.item} disabled={next.disabled ?? false} error={next.error ?? null} onRun={onRun} /></div></MemoryRouter></QueryClientProvider>;
  const view = render(element({ item, ...props }));
  return { fetch, client, onRun, invalidate, rerender: (next: { item: CatalogReview; disabled?: boolean; error?: string | null }) => view.rerender(element(next)),
    section: () => screen.getByTestId('lookup'), details: () => screen.getByRole('region', { name: 'Metadata lookup' }) };
}
/** The name box, opened by Look up another name where the status line did not make it the next step. */
async function nameBox() {
  const toggle = await screen.findByRole('button', { name: 'Look up another name' });
  if (toggle.getAttribute('aria-expanded') !== 'true') fireEvent.click(toggle);
  return screen.findByRole('group', { name: 'Look up by name' });
}
const lookupReads = (fetch: ReturnType<typeof vi.fn>) => fetch.mock.calls.filter(([path]) => String(path).endsWith('/lookup')).length;
beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('before any run the summary says so and prefills the name box with the saved Album title, which submits as a lookup of that kind', async () => {
  const item = catalogReview(), { onRun, rerender, section } = mount(item, notStarted());
  expect(await screen.findByText('Metadata lookup has not run')).toHaveAttribute('role', 'status');
  expect(screen.getByText('Look up another name, or update only the numbers you checked.')).toBeVisible();
  // Looking up a name is the next step, so the box is open.
  expect(screen.getByRole('button', { name: 'Look up another name' })).toHaveAttribute('aria-expanded', 'true');
  expect(await within(section()).findByRole('textbox', { name: 'Name' })).toHaveValue('Synthetic catalog Album');
  // A newly saved title refills the box.
  rerender({ item: { ...item, draft: { ...item.draft, album: { ...item.draft.album, title: 'Synthetic saved correction' } } } });
  await waitFor(() => expect(within(section()).getByRole('textbox', { name: 'Name' })).toHaveValue('Synthetic saved correction'));
  rerender({ item });
  const box = await within(section()).findByRole('group', { name: 'Look up by name' });
  await waitFor(() => expect(within(box).getByRole('textbox', { name: 'Name' })).toHaveValue('Synthetic catalog Album'));
  fireEvent.click(within(box).getByRole('radio', { name: 'Song name' }));
  fireEvent.click(within(box).getByRole('button', { name: 'Look up metadata (free)' }));
  // The Artist field starts with the primary Artists' byline, which the server uses anyway: sent unchanged, the body has no
  // `artist` key, as the hint says.
  expect(onRun).toHaveBeenLastCalledWith('lookup', { kind: 'song', text: 'Synthetic catalog Album' });
  const artist = within(box).getByRole('textbox', { name: 'Artist (optional)' });
  expect(artist).toHaveValue('Synthetic catalog Artist');
  expect(within(box).getByText("Starts with the Album's primary Artists, which are also used when it is left empty.")).toBeVisible();
  // Before any run there is nothing that found nothing: no subtitle hint.
  expect(within(box).queryByText(/without its subtitle/)).not.toBeInTheDocument();
  fireEvent.change(artist, { target: { value: ' Synthetic Typed Artist ' } });
  fireEvent.click(within(box).getByRole('button', { name: 'Look up metadata (free)' }));
  expect(onRun).toHaveBeenLastCalledWith('lookup', { kind: 'song', text: 'Synthetic catalog Album', artist: 'Synthetic Typed Artist' });
  // A blank Artist field is sent as none.
  fireEvent.change(artist, { target: { value: '   ' } });
  fireEvent.click(within(box).getByRole('button', { name: 'Look up metadata (free)' }));
  expect(onRun).toHaveBeenLastCalledWith('lookup', { kind: 'song', text: 'Synthetic catalog Album' });
  // A review not captured for lookup has no identity rows to read.
  expect(screen.queryByRole('region', { name: 'Artists and label' })).not.toBeInTheDocument();
  // A submitted run with an Artist name shows both again, the box being keyed by its run.
  cleanup();
  mount(item, withLookup(lookup => { lookup.input = { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Typed Name', artist: 'Synthetic Typed Artist' } }; }));
  const shown = await nameBox();
  expect(within(shown).getByRole('textbox', { name: 'Name' })).toHaveValue('Synthetic Typed Name');
  expect(within(shown).getByRole('textbox', { name: 'Artist (optional)' })).toHaveValue('Synthetic Typed Artist');
});

test('a completed run that found nothing to use suggests the name without its subtitle, describing the name field; a run that found releases does not', async () => {
  const hint = 'No usable release was found under this name; try it without its subtitle.';
  const noMatch = withLookup(lookup => { Object.assign(lookup, { applied: null, groups: [], preselection: null }); lookup.candidates[0] = { ...lookup.candidates[0], status: 'notMatching', groupKey: null };
    lookup.needsAnswer.conflicts = []; });
  const noRelease = withLookup(lookup => { Object.assign(lookup, { outcome: 'noRelease', applied: null, candidates: [], groups: [], preselection: null }); lookup.needsAnswer.conflicts = []; });
  for (const response of [noMatch, noRelease]) {
    const { section } = mount(applied(), response);
    const box = await within(section()).findByRole('group', { name: 'Look up by name' });
    expect(within(box).getByText(hint)).toBeVisible();
    expect(within(box).getByRole('textbox', { name: 'Name' })).toHaveAccessibleDescription(hint);
    cleanup();
  }
  const { section } = mount(applied());
  await nameBox();
  expect(within(section()).queryByText(hint)).not.toBeInTheDocument();
});

