  const { section } = mount(catalogReview(), notStarted(false));
  expect(await screen.findByText('Metadata lookup is not configured on this server. Edit the draft manually, or use Luna AI (paid).')).toBeInTheDocument();
  expect(within(section()).queryByRole('group', { name: 'Look up by name' })).not.toBeInTheDocument();
