test('the summary polls while a run is active, and a read whose value revision or revision is newer than the detail\'s reads the review detail again, its first read included', async () => {
  const access = { viewerId: viewer, epoch: 0, generation: 1 }, interval = (state: string | null, online = true) =>
    catalogReviewSummaryQuery(access, applied(), online).refetchInterval({ state: { data: state ? withLookup(lookup => { lookup.state = state as Lookup['state']; }) : undefined } });
  expect([interval('queued'), interval('running'), interval('retrying'), interval('complete'), interval(null), interval('running', false)]).toEqual([3000, 3000, 10_000, false, false, false]);
  // A run that is still active, or ends applying nothing new, leaves the value revision and the detail alone; its application does not.
  let state: Lookup['state'] = 'running', valueRevision = 1;
  const rendered = mount(applied(), () => reviewJson({ ...withLookup(lookup => { lookup.state = state; }), valueRevision }));
  await within(rendered.section()).findByText('Looking up metadata in MusicBrainz…');
  const detail = { queryKey: ['admin-catalog-reviews', viewer, expect.any(Number), expect.any(Number), applied().id], exact: true };
  expect(rendered.invalidate).not.toHaveBeenCalledWith(detail);
  state = 'complete';
  await act(async () => { await rendered.client.refetchQueries({ queryKey: ['admin-catalog-reviews'] }); });
  await within(rendered.section()).findByText('Applied release: Synthetic catalog Album (Complete)');
  expect(rendered.invalidate).not.toHaveBeenCalledWith(detail);
  valueRevision = 2;
  await act(async () => { await rendered.client.refetchQueries({ queryKey: ['admin-catalog-reviews'] }); });
  await waitFor(() => expect(rendered.invalidate).toHaveBeenCalledWith(detail));
  cleanup();
  // A run that completed between the detail read and the summary's first read is noticed on that first read.
  const ahead = mount(applied(), { ...reviewLookupResponse(), valueRevision: 2 });
  await waitFor(() => expect(ahead.invalidate).toHaveBeenCalledWith(detail));
  cleanup();
  const newer = mount(applied(), { ...reviewLookupResponse(), revision: 2 });
  await waitFor(() => expect(newer.invalidate).toHaveBeenCalledWith(detail));
});

