test('an active run says whether it is queued or which step runs, with its counts and that the draft can be checked meanwhile; its Details log holds the time since it started and that it keeps running', async () => {
  const active = (state: Lookup['state'], progress: Lookup['progress'] | undefined) => withLookup(lookup => {
    Object.assign(lookup, { run: 4, state, issue: state === 'retrying' ? 'sourceBusy' : null, outcome: null, candidates: [], applied: null, progress });
  }, pairingLookupResponse());
  const ago = (seconds: number) => new Date(Date.now() - seconds * 1000).toISOString(), meanwhile = 'You can check and edit the draft meanwhile; confirm the update once the lookup ends.';
  const cases: [Lookup['state'], Lookup['progress'] | undefined, string, string | RegExp, RegExp | null][] = [
    ['queued', { phase: 'search', done: 0, total: 2, startedAt: ago(20), updatedAt: ago(20) }, 'Queued: waiting to start', meanwhile, /^0:2\d in queue$/],
    ['running', { phase: 'details', done: 3, total: 5, startedAt: ago(14), updatedAt: ago(1) }, 'Lookup running: reading release details (3 of 5)', meanwhile, /^0:1\d elapsed$/],
    ['running', { phase: 'itunes', done: 0, total: 0, startedAt: ago(75), updatedAt: ago(1) }, 'Lookup running: searching iTunes as a fallback', meanwhile, /^1:1\d elapsed$/],
    ['retrying', { phase: 'search', done: 1, total: 2, startedAt: ago(30), updatedAt: ago(1) }, 'Metadata lookup has not finished', /^MusicBrainz is busy or unavailable/, null],
    ['running', undefined, 'Looking up metadata in MusicBrainz…', meanwhile, null]
  ];
  for (const [state, progress, head, line, elapsed] of cases) {
    const { section } = mount(pairingReview(), active(state, progress));
    await expectStatus(head, line);
    // The time and the keeps-running note sit in the log, outside the live region, which never says them.
    const notes = [...statusLine().querySelectorAll(':scope > div:not(:first-child) p')].map(note => note.textContent ?? '');
    expect(within(statusLine()).getByRole('status').textContent).not.toMatch(/elapsed|in queue|keeps running/);
    if (state !== 'retrying') expect(notes).toContain(keepsRunning);
    if (elapsed) expect(notes[0]).toMatch(elapsed);
    expect(primaries(section())).toEqual([]);
    cleanup();
  }
  const { section } = mount(pairingReview(), pairingLookupResponse());
  await expectStatus(completeOne, possiblePairing);
  expect(within(section()).queryByText(keepsRunning)).not.toBeInTheDocument();
});

test('the polite status of a running step does not change between polls; only the elapsed time in its log moves', async () => {
  vi.useFakeTimers({ shouldAdvanceTime: true });
  try {
    const startedAt = new Date(Date.now() - 14_000).toISOString();
    const running = withLookup(lookup => {
      Object.assign(lookup, { run: 4, state: 'running', outcome: null, candidates: [], applied: null, progress: { phase: 'details', done: 3, total: 5, startedAt, updatedAt: startedAt } });
    }, pairingLookupResponse());
    const { fetch } = mount(pairingReview(), running);
    await expectStatus('Lookup running: reading release details (3 of 5)', 'You can check and edit the draft meanwhile; confirm the update once the lookup ends.');
    const elapsed = () => screen.getByText(/ elapsed$/).textContent, before = elapsed();
    await act(async () => { await vi.advanceTimersByTimeAsync(3_000); });
    await waitFor(() => expect(lookupReads(fetch)).toBe(2));
    await waitFor(() => expect(elapsed()).not.toBe(before));
    expect(within(statusLine()).getByRole('status')).toHaveTextContent(/^Lookup running: reading release details \(3 of 5\)$/);
  } finally { vi.useRealTimers(); }
});

